// Нода «Расчёт напоминаний» (Code, режим Run Once for All Items).
// Читает строки таблицы счетов, считает дни просрочки и решает, что отправить сегодня: уровень 1 (день 0), 2 (+3), 3 (+7) или передача владельцу (уровень 4, вручную).
// Ничего не отправляет сама: только готовит список действий. Правила: один счёт не чаще раза в сутки, уровень не повторяется, оплаченный счёт пропускается.
// ===== НАСТРОЙКИ (замените на свои) =====
const S = {
  owner_chat_id: "ВАШ_CHAT_ID",                                   // куда бот присылает карточки «нужно ваше решение» (числовой chat_id вашего Telegram)
  pay_details: "Реквизиты для оплаты: УКАЖИТЕ_СВОИ_РЕКВИЗИТЫ.",   // подставляется в каждое сообщение
  deadline_days: 3,                                               // уровень 3: срок оплаты = сегодня + N дней
  handoff_after_days: 5,                                          // сколько дней ждать после уровня 3, прежде чем звать владельца
};
// ===== ШАБЛОНЫ (те же тексты лежат в scripts_collection.md) =====
const T = {
  1: { subject: "Счёт № {invoice_id}: напоминание об оплате",
       text: "Добрый день, {client}! Напоминаем: сегодня срок оплаты счёта № {invoice_id} на сумму {amount} ₽. {pay_details} Если вы уже оплатили, ничего делать не нужно: просто пришлите платёжку, когда будет удобно. Спасибо!" },
  2: { subject: "Счёт № {invoice_id}: уточнение по оплате",
       text: "Добрый день, {client}! Хотим убедиться, что счёт № {invoice_id} на сумму {amount} ₽ не потерялся: срок оплаты был {due_date}. Подскажите, пожалуйста, когда ждать оплату? Если нужно уточнить реквизиты или закрывающие документы, ответим сразу. {pay_details}" },
  3: { subject: "Счёт № {invoice_id}: просрочка, срок оплаты до {deadline}",
       text: "Добрый день, {client}. Счёт № {invoice_id} на сумму {amount} ₽ просрочен на {days} дн. (срок был {due_date}). Просим оплатить до {deadline}. Если оплата в этот срок невозможна, напишите нам: обсудим рассрочку или частичную оплату. {pay_details}" },
  4: { subject: "",
       text: "Нужно ваше решение. Счёт № {invoice_id}, клиент {client}, сумма {amount} ₽, просрочка {days} дн. Напоминания 1-3 отправлены, оплаты нет. Бот больше ничего клиенту не отправит. Черновик досудебного уведомления (проверьте, поправьте и отправьте сами): «Уважаемый {client}! По счёту № {invoice_id} на сумму {amount} ₽ со сроком оплаты {due_date} оплата не поступила. Просим оплатить до {deadline}.»" },
};
const DAY = 86400000;
function parseDate(v) {
  if (v === undefined || v === null || v === "") return null;
  if (typeof v === "number") return v > 20000 ? new Date(Date.UTC(1899, 11, 30) + Math.round(v) * DAY) : null;   // серийный номер даты Excel
  const s = String(v).trim();
  let m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s);
  if (m) return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  m = /^(\d{2})\.(\d{2})\.(\d{4})/.exec(s);
  if (m) return new Date(Date.UTC(+m[3], +m[2] - 1, +m[1]));
  return null;
}
const iso = (d) => d.toISOString().slice(0, 10);
const ru = (d) => iso(d).split("-").reverse().join(".");
const money = (n) => String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, " ");
const fill = (s, v) => s.replace(/\{(\w+)\}/g, (_, k) => (v[k] !== undefined ? v[k] : "{" + k + "}"));

const t0 = parseDate($now.toISODate());
const out = [];
for (const it of $input.all()) {
  const r = it.json;
  const id = String(r.invoice_id || "").trim();
  if (!id) continue;
  const status = String(r.status || "open").trim().toLowerCase();
  if (status !== "open") continue;                                  // оплачен или передан человеку: бот молчит
  const due = parseDate(r.due_date);
  if (!due) continue;
  const days = Math.round((t0 - due) / DAY);
  const last = Number(r.last_level) || 0;
  const lastSent = parseDate(r.last_sent_at);
  if (lastSent && iso(lastSent) === iso(t0)) continue;              // не чаще одного сообщения в сутки на счёт
  let level = 0, kind = "send";
  const target = days >= 7 ? 3 : days >= 3 ? 2 : days >= 0 ? 1 : 0;
  if (last === 3 && days >= 7 && lastSent && Math.round((t0 - lastSent) / DAY) >= S.handoff_after_days) { level = 4; kind = "handoff"; }
  else if (target > last) level = target;
  if (!level) continue;
  const channel = String(r.contact_channel || "none").trim().toLowerCase();
  const contact = String(r.contact === undefined ? "" : r.contact).trim();
  let action = "handoff";                                           // по умолчанию звать владельца
  if (level <= 3) {
    if (channel === "email" && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contact)) action = "send_email";
    else if (channel === "telegram" && /^-?\d{5,}$/.test(contact)) action = "send_telegram";
    else kind = "draft";                                            // канала нет или контакт неверный: владелец получает текст и пишет сам
  }
  const dl = new Date(t0.getTime() + S.deadline_days * DAY);
  const v = { client: r.client || "клиент", invoice_id: id, amount: money(r.amount), due_date: ru(due), days: String(days), deadline: ru(dl), pay_details: S.pay_details };
  const tpl = T[level];
  const ownerText = level === 4 ? fill(T[4].text, v) : "Нужно написать клиенту вручную (канал не задан или контакт неверный). Счёт № " + id + ", клиент " + v.client + ". Текст уровня " + level + ": " + fill(T[level].text, v);
  out.push({ json: {
    invoice_id: id, client: v.client, level, kind, action, channel, to: contact, owner_chat_id: S.owner_chat_id,
    subject: fill(tpl.subject, v), text: action === "handoff" ? ownerText : fill(tpl.text, v),
    days_overdue: days, new_level: level, new_status: level === 4 ? "handoff" : "open", sent_at: iso(t0),
  } });
}
return out;

// Нода «Применить отметки» (Code, Run Once for All Items): вносит в таблицу уровень, дату отправки и статус только для тех счетов, где отправка прошла успешно (sent_ok).
// Если отправка не удалась, счёт не отмечается и завтра получит тот же уровень снова (повтор безопаснее пропуска).
const COLS = ["invoice_id", "client", "contact_channel", "contact", "amount", "due_date", "status", "last_level", "last_sent_at", "note"];
const rows = $("Таблица счетов").all().map((i) => i.json);
const marks = {};
for (const it of $input.all()) { const m = it.json; if (m.sent_ok) marks[String(m.invoice_id)] = m; }
return rows.filter((r) => String(r.invoice_id || "").trim()).map((r) => {
  const o = {};
  for (const c of COLS) o[c] = r[c] === undefined || r[c] === null ? "" : r[c];
  const m = marks[String(r.invoice_id).trim()];
  if (m) { o.last_level = m.new_level; o.last_sent_at = m.sent_at; o.status = m.new_status; }
  return { json: o };
});

// Нода «Отметить оплату» (Code, Run Once for All Items): по входящему вебхуку ставит статус «paid» счёту с этим invoice_id.
const COLS = ["invoice_id", "client", "contact_channel", "contact", "amount", "due_date", "status", "last_level", "last_sent_at", "note"];
const body = $("Оплата (вебхук)").first().json.body || {};
const id = String(body.invoice_id || "").trim();
if (!id) throw new Error("В вебхуке нет invoice_id");
let found = false;
const rows = $("Таблица (оплата)").all().map((i) => i.json).filter((r) => String(r.invoice_id || "").trim()).map((r) => {
  const o = {};
  for (const c of COLS) o[c] = r[c] === undefined || r[c] === null ? "" : r[c];
  if (String(o.invoice_id).trim() === id) { o.status = "paid"; o.note = (o.note ? o.note + "; " : "") + "оплачен " + $now.toISODate(); found = true; }
  return { json: o };
});
if (!found) throw new Error("Счёт " + id + " не найден в таблице");
return rows;
